import math

def build_instance(rng):
    point_count = rng.randint(2, 10)
    subset_size = rng.randint(1, point_count)
    x_sum = rng.randint(1, point_count * subset_size)
    answer = math.comb(point_count, subset_size)
    check = sum((1 for _ in range(math.comb(point_count, subset_size))))
    parameters = {'point_count': point_count, 'subset_size': subset_size, 'x_sum': x_sum}
    return (parameters, answer, check)



